/* ============================================================
   GRAPH BUILD + DIJKSTRA
   ============================================================ */
function buildGraph(floor) {
          const nodes = {};
          floor.rooms.forEach(r => nodes[r.id] = r);
          floor.junctions.forEach(j => nodes[j.id] = j);
          const adj = {};
          Object.keys(nodes).forEach(id => adj[id] = []);
          floor.edges.forEach(([a, b]) => {
                    const na = nodes[a], nb = nodes[b];
                    if (!na || !nb) return;
                    const d = Math.hypot(na.x - nb.x, na.y - nb.y);
                    adj[a].push({ to: b, w: d });
                    adj[b].push({ to: a, w: d });
          });
          return { nodes, adj };
}

function dijkstra(graph, startId, endId) {
          const { nodes, adj } = graph;
          const dist = {}, prev = {}, visited = {};
          Object.keys(nodes).forEach(id => dist[id] = Infinity);
          dist[startId] = 0;
          const queue = new Set(Object.keys(nodes));
          while (queue.size) {
                    let u = null, best = Infinity;
                    queue.forEach(id => { if (dist[id] < best) { best = dist[id]; u = id; } });
                    if (u === null) break;
                    queue.delete(u);
                    if (u === endId) break;
                    (adj[u] || []).forEach(edge => {
                              const alt = dist[u] + edge.w;
                              if (alt < dist[edge.to]) {
                                        dist[edge.to] = alt;
                                        prev[edge.to] = u;
                              }
                    });
          }
          if (dist[endId] === Infinity) return null;
          const path = [];
          let cur = endId;
          while (cur !== undefined) {
                    path.unshift(cur);
                    cur = prev[cur];
          }
          return path;
}

