const compassLabel = document.getElementById('compassLabel');

function populateFloorSelect() {
          floorSelect.innerHTML = '';
          Object.entries(ROOM_DATA).forEach(([key, floor]) => {
                    const opt = document.createElement('option');
                    opt.value = key; opt.textContent = floor.label;
                    floorSelect.appendChild(opt);
          });
          floorSelect.value = currentFloorKey;
}

function populateRoomSelects() {
          const floor = ROOM_DATA[currentFloorKey];
          const rooms = [...floor.rooms].sort((a, b) => a.label.localeCompare(b.label));
          [fromSelect, toSelect, calibRoomSelect].forEach(sel => sel.innerHTML = '');
          rooms.forEach(r => {
                    [fromSelect, toSelect, calibRoomSelect].forEach(sel => {
                              const opt = document.createElement('option');
                              opt.value = r.id; opt.textContent = r.label;
                              sel.appendChild(opt);
                    });
          });
          if (rooms.length > 1) toSelect.selectedIndex = 1;
}

function loadFloor(key) {
          currentFloorKey = key;
          const floor = ROOM_DATA[key];
          currentGraph = buildGraph(floor);
          floorImg.src = floor.image;
          populateRoomSelects();
          clearRoute();
          renderRoomDots();
          compassLabel.textContent = 'N \u2192 E \u2192 S \u2192 W (per plan)';
}

function clearRoute() {
          overlay.innerHTML = '';
          markerLayer.innerHTML = '';
          stepsList.innerHTML = '';
          emptyHint.style.display = 'block';
          statusMsg.textContent = '';
}

function renderRoomDots() {
          roomDotLayer.innerHTML = '';
          const floor = ROOM_DATA[currentFloorKey];
          floor.rooms.forEach(r => {
                    const dot = document.createElement('div');
                    dot.className = 'room-dot';
                    dot.style.left = r.x + '%';
                    dot.style.top = r.y + '%';
                    dot.title = r.label;
                    dot.addEventListener('click', () => {
                              if (!calibrating) {
                                        statusMsg.textContent = r.label + '  (' + r.x.toFixed(1) + '%, ' + r.y.toFixed(1) + '%)';
                              }
                    });
                    roomDotLayer.appendChild(dot);
          });
}

function pathToCoords(path) {
          const { nodes } = currentGraph;
          return path.map(id => nodes[id]);
}

function drawRoute(path) {
          const coords = pathToCoords(path);
          overlay.setAttribute('viewBox', '0 0 100 100');
          overlay.setAttribute('preserveAspectRatio', 'none');
          overlay.innerHTML = '';

          const pts = coords.map(c => c.x + ',' + c.y).join(' ');
          const glow = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
          glow.setAttribute('points', pts);
          glow.setAttribute('fill', 'none');
          glow.setAttribute('stroke', '#5ee1ff');
          glow.setAttribute('stroke-width', '1.6');
          glow.setAttribute('stroke-opacity', '0.35');
          glow.setAttribute('stroke-linecap', 'round');
          glow.setAttribute('stroke-linejoin', 'round');
          glow.setAttribute('vector-effect', 'non-scaling-stroke');
          overlay.appendChild(glow);

          const line = document.createElementNS('http://www.w3.org/2000/svg', 'polyline');
          line.setAttribute('points', pts);
          line.setAttribute('fill', 'none');
          line.setAttribute('stroke', '#5ee1ff');
          line.setAttribute('stroke-width', '0.6');
          line.setAttribute('stroke-linecap', 'round');
          line.setAttribute('stroke-linejoin', 'round');
          line.setAttribute('stroke-dasharray', '2.2 1.6');
          line.setAttribute('vector-effect', 'non-scaling-stroke');
          const len = line.getTotalLength ? null : null;
          line.style.animation = 'dashmove 1.1s linear infinite';
          overlay.appendChild(line);

          const styleTag = document.createElementNS('http://www.w3.org/2000/svg', 'style');
          styleTag.textContent = '@keyframes dashmove { to { stroke-dashoffset:-38; } }';
          overlay.appendChild(styleTag);

          markerLayer.innerHTML = '';
          const start = coords[0], end = coords[coords.length - 1];
          addMarker(start, 'start');
          addMarker(end, 'end');
}

function addMarker(node, kind) {
          const el = document.createElement('div');
          el.className = 'marker ' + kind;
          el.style.left = node.x + '%';
          el.style.top = node.y + '%';
          el.innerHTML = '<div class="dot"></div><div class="lbl">' + node.label + '</div>';
          markerLayer.appendChild(el);
}

function renderDirections(path) {
          const { nodes } = currentGraph;
          stepsList.innerHTML = '';
          emptyHint.style.display = 'none';
          const roomStops = path.map(id => nodes[id]).filter(n => n.kind === 'room' || n === nodes[path[0]] || n === nodes[path[path.length - 1]]);
          const startLabel = nodes[path[0]].label;
          const endLabel = nodes[path[path.length - 1]].label;

          const li0 = document.createElement('li');
          li0.textContent = 'Start at ' + startLabel + '.';
          stepsList.appendChild(li0);

          const junctionsPassed = path.slice(1, -1).filter(id => nodes[id].kind === 'junction').length;
          if (junctionsPassed > 0) {
                    const li1 = document.createElement('li');
                    li1.textContent = 'Follow the corridor, passing ' + junctionsPassed + ' junction' + (junctionsPassed === 1 ? '' : 's') + ' along the way.';
                    stepsList.appendChild(li1);
          }

          const liEnd = document.createElement('li');
          liEnd.textContent = 'Arrive at ' + endLabel + '.';
          stepsList.appendChild(liEnd);
}

function findRoute() {
          const fromId = fromSelect.value, toId = toSelect.value;
          if (!fromId || !toId) { return; }
          if (fromId === toId) {
                    statusMsg.textContent = 'Pick two different rooms.';
                    return;
          }
          const path = dijkstra(currentGraph, fromId, toId);
          if (!path) {
                    statusMsg.textContent = 'No route found on this floor between those rooms.';
                    clearRoute();
                    return;
          }
          statusMsg.textContent = '';
          drawRoute(path);
          renderDirections(path);
}

/* ============================================================
   CALIBRATION MODE
   ============================================================ */
function refreshCalibOutput() {
          const floor = ROOM_DATA[currentFloorKey];
          const data = floor.rooms.map(r => ({ id: r.id, label: r.label, x: Number(r.x.toFixed(2)), y: Number(r.y.toFixed(2)) }));
          calibOutput.value = JSON.stringify(data, null, 2);
}

calibBtn.addEventListener('click', () => {
          calibrating = !calibrating;
          calibBtn.classList.toggle('active', calibrating);
          calibBox.classList.toggle('show', calibrating);
          mapWrap.classList.toggle('calibrating', calibrating);
          if (calibrating) {
                    calibSelectedRoomId = calibRoomSelect.value;
                    refreshCalibOutput();
          }
});

calibRoomSelect.addEventListener('change', () => {
          calibSelectedRoomId = calibRoomSelect.value;
});

mapWrap.addEventListener('click', (e) => {
          if (!calibrating) return;
          const rect = mapWrap.getBoundingClientRect();
          const xPct = ((e.clientX - rect.left) / rect.width) * 100;
          const yPct = ((e.clientY - rect.top) / rect.height) * 100;
          const floor = ROOM_DATA[currentFloorKey];
          const room = floor.rooms.find(r => r.id === calibSelectedRoomId);
          if (!room) return;
          room.x = Math.max(0, Math.min(100, xPct));
          room.y = Math.max(0, Math.min(100, yPct));
          currentGraph = buildGraph(floor);
          renderRoomDots();
          refreshCalibOutput();
          clearRoute();
});

copyBtn.addEventListener('click', () => {
          calibOutput.select();
          document.execCommand('copy');
          copyBtn.textContent = 'Copied!';
          setTimeout(() => copyBtn.textContent = 'Copy JSON', 1200);
});

/* ============================================================
   EVENTS + INIT
   ============================================================ */
floorSelect.addEventListener('change', () => loadFloor(floorSelect.value));
goBtn.addEventListener('click', findRoute);
swapBtn.addEventListener('click', () => {
          const f = fromSelect.value;
          fromSelect.value = toSelect.value;
          toSelect.value = f;
});

populateFloorSelect();
loadFloor(currentFloorKey);